2472	    // We always reset our semantic prompt state
2473	    cursor.semantic_content = old_semantic;
2474	    cursor.semantic_content_clear_eol = old_semantic_clear;
2475	    switch (old_semantic) {
2476	        .output, .input => {},
2477	        .prompt => cursor.page_row.semantic_prompt = .prompt_continuation,
2478	    }
