   343	/// it yourself.
   344	pub fn init(
   345	    io_impl: std.Io,
   346	    alloc: Allocator,
   347	    opts: Options,
   348	) !Terminal {
   349	    const cols = opts.cols;
   350	    const rows = opts.rows;
   351	
